/* Signature Danish Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Jenslind": "From Jens + lind (lime/linden).", "Mettehav": "From Mette + hav (sea): 'pearl of the sea'.", "Larsbjorn": "From Lars + bjorn (bear).", "Annefryd": "From Anne + fryd (joy): 'graceful joy'.", "Peterstrand": "From Peter + strand (beach).", "Hannevig": "From Hanne + vig (bay).", "Jenslindsen": "Signature surname in -sen style built on Jenslind.", "Mettehavsen": "Signature surname in -sen style.", "Larsbjornsen": "Signature surname in -sen style.", "Annefrydsen": "Signature surname in -sen style."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Jenslind';
console.log(lookup(q));

